package com.supermercado.pos.ui;

import javax.swing.*;import java.awt.*;import java.sql.*;import java.util.*;import com.supermercado.pos.dao.*;import com.supermercado.pos.util.*;
public final class UI {private UI(){}public static JPanel panel(){JPanel p=new JPanel(new GridLayout(0,2,8,8));p.setBorder(BorderFactory.createEmptyBorder(14,14,14,14));return p;}public static JTextField campo(JPanel p,String titulo){p.add(new JLabel(titulo));JTextField f=new JTextField(20);p.add(f);return f;}public static JPasswordField clave(JPanel p,String titulo){p.add(new JLabel(titulo));JPasswordField f=new JPasswordField(20);p.add(f);return f;}public static void mensaje(Component c,Object m){JOptionPane.showMessageDialog(c,m);}public static void error(Component c,Exception e){JOptionPane.showMessageDialog(c,e.getMessage(),"Error",JOptionPane.ERROR_MESSAGE);}public static void accion(Component c,Runnable r){try{r.run();}catch(Exception e){error(c,e);}}public static String pedir(Component c,String texto){return JOptionPane.showInputDialog(c,texto);}public static void permiso(String p){com.supermercado.pos.servicio.Operaciones.permiso(p);}public static void mostrar(String titulo,String sql){try(Connection c=Conexion.obtener()){java.util.List<Object[]> filas=Sql.filas(c,sql);StringBuilder b=new StringBuilder();for(Object[] f:filas)b.append(Arrays.toString(f)).append("\n");JTextArea a=new JTextArea(b.toString(),18,65);a.setEditable(false);JOptionPane.showMessageDialog(null,new JScrollPane(a),titulo,JOptionPane.INFORMATION_MESSAGE);}catch(Exception e){error(null,e);}}}